  async agentChat(message, history = [], sessionId, attachments) {
    const payload = { message, history, context: { source: 'web' }, session_id: sessionId || '' };
    if (attachments) payload.attachments = attachments;
    return await this.api('/api/agent/chat', payload);
  }

  async getAgentSessions(search) {
    try {
      // cache: 'no-store' 强制每次获取最新会话数据，避免浏览器缓存导致"后端已追加、前端拿旧数据"
      // search: 关键词 → 后端 rg 加速全文搜索（会话名称+消息内容）
      const q = (search || '').trim();
      const url = q ? `${API_BASE}/api/agent/sessions?search=${encodeURIComponent(q)}` : `${API_BASE}/api/agent/sessions`;
      const res = await fetch(url, { cache: 'no-store' });
      return await res.json();
    } catch (e) {
      return { code: -1, msg: e.message };
    }
  }
  // 只读获取单个会话状态（不影响Agent运行）
  async getAgentSession(sessionId) {
    try {
      // cache: 'no-store'：轮询/刷新必须拿到后端最新追加的数据，禁止命中浏览器缓存
      const res = await fetch(`${API_BASE}/api/agent/sessions/${encodeURIComponent(sessionId)}`, { cache: 'no-store' });
      return await res.json();
    } catch (e) {
      return { code: -1, msg: e.message };
    }
  }
  async createAgentSession() {
    return this.api('/api/agent/sessions/create');
  }
  async switchAgentSession(sessionId) {
    return this.api('/api/agent/sessions/switch', { session_id: sessionId });
  }
  async deleteAgentSession(sessionId) {
    return this.api('/api/agent/sessions/delete', { session_id: sessionId });
  }

