  downloadFile(path) {
    const a = document.createElement('a');
    a.href = this.getDownloadUrl(path);
    a.download = '';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
  }

  connectWS() {
    var base = API_BASE.replace(/^http/, 'ws');
    var url = base + '/ws?app=' + this.appId + '&id=' + this.sessionId + '&type=main';

    try {
      this.ws = new WebSocket(url);
    } catch (e) {
      console.error('WS connect error:', e);
      this.reconnectTimer = setTimeout(() => this.connectWS(), 5000);
      return;
    }

    this.ws.onopen = () => {
      this.wsConnected = true;
      updateWsStatus(true);
      // 重连后刷新文件树，恢复实时更新（树已初始化才刷新，避免首连空树）
      if (state.expandedDirs.size > 0) refreshTree();
    };

    this.ws.onclose = () => {
      this.wsConnected = false;
      updateWsStatus(false);
      this.reconnectTimer = setTimeout(() => this.connectWS(), 3000);
    };

    this.ws.onerror = () => {
      this.wsConnected = false;
      updateWsStatus(false);
    };

    this.ws.onmessage = (event) => {
      try {
        const msg = JSON.parse(event.data);
        handleWSMessage(msg);
      } catch (e) {}
    };
  }

  sendWS(cmd, param = {}) {
    if (this.ws && this.ws.readyState === WebSocket.OPEN) {
      this.ws.send(JSON.stringify({ cmd, reqId: Date.now(), param }));
    }
  }

