// ─── 协同副本：挂载到虚拟标签页（对标 Monaco 单实例视图）──────
// 单容器 collabEditorArea，同一时刻最多一个协同实例活跃。
// 切走标签时实例保留（WS 不断），切回时复用；打开新协同文件时若已有其他实例则先 close。

// 虚拟副本路径：源路径 + "::collab"
function collabCopyPath(srcPath) { return srcPath + '::collab'; }

async function openCollabCopy(srcPath) {
  const collabPath = collabCopyPath(srcPath);
  const existing = state.openTabs.find(t => t.path === collabPath);
  if (existing) { switchToTab(collabPath); return; }
  // 打开协同副本可能伴随创建新副本：失效内存缓存触发下次重扫（重扫成功会重新写 LS）。
  // 不清 localStorage：会话恢复会调 openCollabCopy，清 LS 会导致刷新后缓存永久丢失。
  _collabListCache.at = 0;
  // 协同编辑器单容器：若已有其他协同实例，先关闭（释放容器与 WS）
  if (window.CollabEditor && window.CollabEditor.isActive()) {
    // 找到当前活跃的协同 srcPath 并关闭其标签
    for (var i = 0; i < state.openTabs.length; i++) {
      var t = state.openTabs[i];
      if (t._isCollab && window.CollabEditor.hasInstance(t._srcPath)) {
        // 直接关闭标签（会触发 closeTab → 销毁实例）
        closeTab(t.path);
        break;
      }
    }
  }
  const name = srcPath.split('/').pop();
  state.openTabs.push({ path: collabPath, name: name + ' · 协同', modified: false, _isCollab: true, _srcPath: srcPath });
  addTab(collabPath, name + ' · 协同');
  switchToTab(collabPath);
  _saveSession();  // 立即持久化，确保刷新后会话恢复能找回协同标签
  // 由 switchTo 的 _isCollab 分支触发 CollabEditor.open
  showToast('已打开协同副本（独立会话，源文件不受影响；保存需显式「保存到源文件」）', 'info');
}

// 把协同副本内容写回源文件（显式保存，不动自动保存）
async function saveCollabCopyBack() {
  const tab = state.openTabs.find(t => t.path === state.activeTab && t._isCollab);
  if (!tab || !tab._srcPath) { showToast('当前不是协同副本', 'error'); return; }
  // 从协同实例取内容（getEditorContent 取的是主编辑器，协同独立）
  const vd = window.CollabEditor ? window.CollabEditor.getVditor(tab._srcPath) : null;
  if (!vd) { showToast('协同实例未就绪', 'error'); return; }
  var content = vd.getValue();
  if (isRmdPath(tab._srcPath) && window.editorSourceToRmd) {
    try { content = window.editorSourceToRmd(content); } catch (e) {}
  }
  const res = await client.putFile(tab._srcPath, content);
  if (res.code === 0) {
    state.fileContents[tab._srcPath] = content;
    state.originalContents[tab._srcPath] = content;
    markTabModified(state.activeTab, false);
    showToast('已保存到源文件: ' + tab._srcPath.split('/').pop(), 'success');
  } else {
    showToast('保存到源文件失败: ' + (res.msg || ''), 'error');
  }
}

// 协同编辑器内部"退出协同"按钮触发时，关闭对应虚拟标签
// 由 collab-editor.js 的 close() 回调，避免与 closeTab 主动关闭循环
window._collabCloseTab = function (srcPath) {
  const collabPath = collabCopyPath(srcPath);
  if (state.openTabs.find(t => t.path === collabPath)) {
    closeTab(collabPath);
  }
};

// ─── Editor Service (解耦编辑器与面包屑/文件树) ──────────

let _editorOpenGen = 0;  // 代际计数器：防止快速连续打开文件时旧请求覆盖新状态

const editorService = {
  async open(path, forceFresh) {
    // 如果活动 pane 是分屏编辑器，在该 pane 中打开
    if (!forceFresh && _splitActive && _activePaneId !== '0' && _activePaneId !== _agentPaneId) {
      await this.openInPane(path, _activePaneId);
      return;
    }

    const ext = path.includes('.') ? ('.' + path.split('.').pop().toLowerCase()) : '';
    // 图片文件 → 图片浏览器标签页（多格式、多实例）
    if (_isImageFile(path)) {
      if (state.openTabs.find(t => t.path === path)) {
        this.switchTo(path);
        return;
      }
      var imgName = path.split('/').pop();
      state.openTabs.push({ path, name: imgName, modified: false, _isImage: true });
      addTab(path, imgName);
      this.switchTo(path);
      this._addRecent(path, imgName);
      showToast(`已打开: ${imgName}`, 'info');
      return;
    }
    if (ext === '.pdf') {
      if (state.openTabs.find(t => t.path === path)) {
        this.switchTo(path);
        return;
      }
      var pdfName = path.split('/').pop();
      state.openTabs.push({ path, name: pdfName, modified: false, _isPdf: true });
      addTab(path, pdfName);
      var ok = await _loadAndRenderPdf(path);
      if (ok) {
        this.switchTo(path);
        this._addRecent(path, pdfName);
        showToast(`已打开: ${pdfName}`, 'info');
      } else {
        closeTab(path);
      }
      return;
    }
    if (ext === '.docx' || ext === '.xlsx' || ext === '.pptx') {
      if (state.openTabs.find(t => t.path === path)) {
        this.switchTo(path);
        return;
      }
      var officeName = path.split('/').pop();
      state.openTabs.push({ path, name: officeName, modified: false, _isOffice: true });
      addTab(path, officeName);
      this.switchTo(path);
      this._addRecent(path, officeName);
      return;
    }
    if (ext === '.kmind') {
      if (state.openTabs.find(t => t.path === path)) {
        this.switchTo(path);
        return;
      }
      var oldKmindTab = state.openTabs.find(t => t._isKmind);
      if (oldKmindTab) closeTab(oldKmindTab.path);
      var kmindRes = await client.getFile(path);
      if (kmindRes.code !== 0 || !kmindRes.data) {
        var kmindSrcRes = await client.api('/api/data/projects/readFile', { path });
        if (kmindSrcRes.code !== 0 || !kmindSrcRes.data) { showToast('打开失败', 'error'); return; }
        kmindRes = kmindSrcRes;
      }
      var kmindContent = kmindRes.data.content;
      var kmindFileName = path.split('/').pop();
      state.fileContents[path] = kmindContent;
      state.openTabs.push({ path: path, name: kmindFileName, modified: false, _isKmind: true });
      addTab(path, kmindFileName);
      this.switchTo(path);
      this._addRecent(path, kmindFileName);
      // After switch, load data into iframe
      setTimeout(function() { kmindLoadData(path, kmindContent); }, 300);
      return;
    }
    if (ext === '.html' || ext === '.htm') {
      const encodedPath = path.split('/').map(s => encodeURIComponent(s)).join('/');
      window.open(API_BASE + '/api/file/download/' + encodedPath + '?preview=true', '_blank');
      return;
    }
    // .tex 文件 → 弹窗选择 Texpile / Monaco（可拔插：texpile 不可用时直接 Monaco）
    if (ext === '.tex') {
      var texChoice = await texChooseEditor(path);
      if (texChoice === 'texpile') {
        await openTex(path);
        return;
      }
      // 'monaco' 或其他值：走下方 Monaco 分支
    }
    // 代码/脚本文件 → Monaco Editor（每个文件独立标签页）
    var _codeExts = ['.py','.js','.ts','.jsx','.tsx','.r','.cpp','.c','.h','.java','.go','.rs','.rb','.php','.swift','.kt','.scala','.sh','.bash','.zsh','.ps1','.bat','.sql','.css','.scss','.less','.vue','.svelte','.yaml','.yml','.toml','.json','.xml','.tex','.gradle','.sbt','.pl','.pm','.lua','.hs','.clj','.ex','.erl'];
    if (_codeExts.includes(ext)) {
      var monoRes = await client.getFile(path);
      if (monoRes.code !== 0 || !monoRes.data) { showToast('打开失败', 'error'); return; }
      // 保存当前 Monaco 内容
      if (_monacoCurrentFile && _monacoEditor) {
        _monacoFiles[_monacoCurrentFile] = _monacoEditor.getValue();
      }
      _monacoCurrentFile = path;
      _monacoFiles[path] = monoRes.data.content;
      _monacoSrcFile = null;
      var monoName = path.split('/').pop();
      var existingTab = state.openTabs.find(function(t) { return t.path === path; });
      if (existingTab) {
        existingTab.modified = false;
        this.switchTo(path);
      } else {
        state.openTabs.push({ path: path, name: monoName, modified: false, _isMonaco: true });
        addTab(path, monoName);
        this.switchTo(path);
        this._addRecent(path, monoName);
      }
      // 初始化/加载 Monaco
      if (!_monacoEditor) {
        document.getElementById('monacoEditorWrap').innerHTML = '';
        _initMonaco(document.getElementById('monacoEditorWrap'), monoRes.data.content, path);
      }
      showToast('已打开: ' + monoName, 'info');
      return;
    }
    if (!forceFresh && state.openTabs.find(t => t.path === path)) {
      this.switchTo(path);
      return;
    }
    // forceFresh 时清除旧缓存，确保从服务器重新读取
    if (forceFresh) {
      delete state.fileContents[path];
      delete state.originalContents[path];
    }
    // 代际计数器：await 期间若用户又打开了别的文件，放弃本次操作
    const gen = ++_editorOpenGen;
    // 先尝试 FileSyncEngine（EXPOSED_DIRS 内的文件），失败则 fallback 到项目源码 API
    let content = null, entry = null;
    const res = await client.getFile(path);
    if (gen !== _editorOpenGen) return;  // 已被新请求取代
    if (res.code === 0 && res.data) {
      content = res.data.content;
      entry = res.data.entry;
    } else {
      // fallback: 尝试项目源码 API（不受 EXPOSED_DIRS 限制）
      const srcRes = await client.api('/api/data/projects/readFile', { path });
      if (gen !== _editorOpenGen) return;  // 已被新请求取代
      if (srcRes.code === 0 && srcRes.data) {
        content = srcRes.data.content;
        entry = { name: srcRes.data.name || path.split('/').pop(), path, is_dir: false, ext: srcRes.data.ext || '' };
      }
    }
    if (gen !== _editorOpenGen) return;  // 已被新请求取代
    if (content === null) {
      showToast('打开失败: 文件未找到', 'error');
      return;
    }
    state.fileContents[path] = content;
    state.originalContents[path] = content;
    const name = entry ? (entry.name || path.split('/').pop()) : path.split('/').pop();
    var existingTab = state.openTabs.find(function(t) { return t.path === path; });
    if (existingTab) {
      // forceFresh 且 tab 已存在：更新内容后切换，不重复添加
      this.switchTo(path);
    } else {
      state.openTabs.push({ path, name, modified: false });
      addTab(path, name);
      this.switchTo(path);
      this._addRecent(path, name);
    }
    showToast(`已打开: ${name}`, 'info');
  },

  openWithContent(path, content) {
    if (state.openTabs.find(t => t.path === path)) {
      this.switchTo(path);
      return;
    }
    const name = path.split('/').pop();
    state.fileContents[path] = content;
    state.originalContents[path] = content;
    state.openTabs.push({ path, name, modified: false });
    addTab(path, name);
    this.switchTo(path);
    this._addRecent(path, name);
    showToast(`已打开: ${name}`, 'info');
  },

  switchTo(path) {
    if (window.autoSaveScheduler && path !== state.activeTab && _autoSaveMainDirty()) {
      window.autoSaveScheduler.flush('main');
    }
    // 欢迎页
    if (path === '__welcome__') {
      state.activeTab = path;
      document.querySelectorAll('.tab').forEach(t => t.classList.toggle('active', t.dataset.path === path));
      document.querySelectorAll('.tree-item').forEach(t => t.classList.remove('active'));
      document.getElementById('statusPath').textContent = '首页';
      hideEditor();
      return;
    }
    // 保存前一个浏览器页签的状态
    var prevTab = state.openTabs.find(function(t) { return t.path === state.activeTab; });
    if (prevTab && prevTab._isBrowser) {
      var f = document.getElementById('browserFrame');
      var inp = document.getElementById('browserUrlInput');
      if (f && inp) {
        prevTab._browserUrl = f.getAttribute('data-url') || inp.value || 'about:blank';
      }
    }
    // 切走 Monaco 时保存当前内容（在更新 activeTab 之前）
    if (_monacoCurrentFile && _monacoEditor) {
      var prevTab = state.openTabs.find(function(t) { return t.path === state.activeTab; });
      if (prevTab && prevTab._isMonaco) _monacoFiles[state.activeTab] = _monacoEditor.getValue();
    }
    state.activeTab = path;
    document.querySelectorAll('.tab').forEach(t => t.classList.toggle('active', t.dataset.path === path));
    document.querySelectorAll('.tree-item').forEach(t => t.classList.toggle('active', t.dataset.path === path));
    updatePathBar(path);
    document.getElementById('statusPath').textContent = path;
    updateKnitButtonVisibility(path);
    var tab = state.openTabs.find(t => t.path === path);
    var ext = path.includes('.') ? ('.' + path.split('.').pop().toLowerCase()) : '';
    // 非图片标签页时统一隐藏图片浏览器（图片分支随后会重新显示）
    document.getElementById('imageViewer').style.display = 'none';
    if (ext === '.pdf') {
      document.getElementById('slidesEditorView').style.display = 'none';
      document.getElementById('welcomeScreen').style.display = 'none';
      document.getElementById('vditor').style.display = 'none';
      document.getElementById('plainEditor').style.display = 'none';
      document.getElementById('pdfViewer').style.display = 'flex';
      document.getElementById('kmindEditorView').style.display = 'none';
      document.getElementById('jupyterEditorView').style.display = 'none';
      document.getElementById('monacoEditorView').style.display = 'none';
      document.getElementById('collabEditorView').style.display = 'none';
      document.getElementById('browserView').style.display = 'none';
      document.getElementById('texpileEditorView').style.display = 'none';
      if (state.pdfPath !== path) _loadAndRenderPdf(path);
      return;
    }
    if (tab && tab._isImage) {
      document.getElementById('slidesEditorView').style.display = 'none';
      document.getElementById('welcomeScreen').style.display = 'none';
      document.getElementById('vditor').style.display = 'none';
      document.getElementById('plainEditor').style.display = 'none';
      document.getElementById('pdfViewer').style.display = 'none';
      document.getElementById('kmindEditorView').style.display = 'none';
      document.getElementById('jupyterEditorView').style.display = 'none';
      document.getElementById('monacoEditorView').style.display = 'none';
      document.getElementById('collabEditorView').style.display = 'none';
      document.getElementById('browserView').style.display = 'none';
      document.getElementById('officeEditorView').style.display = 'none';
      document.getElementById('texpileEditorView').style.display = 'none';
      document.getElementById('imageViewer').style.display = 'flex';
      // 载入图片（多实例：每个标签页独立 src 与缩放状态）
      var img = document.getElementById('imageViewerImg');
      var nameEl = document.getElementById('imageViewerName');
      if (img) img.src = _imageFileUrl(path);
      if (nameEl) nameEl.textContent = tab.name || path.split('/').pop();
      _imgApply(path);
      return;
    }
    if (tab && tab._isSlides) {
      document.getElementById('pdfViewer').style.display = 'none';
      document.getElementById('welcomeScreen').style.display = 'none';
      document.getElementById('vditor').style.display = 'none';
      document.getElementById('plainEditor').style.display = 'none';
      document.getElementById('slidesEditorView').style.display = 'flex';
      document.getElementById('kmindEditorView').style.display = 'none';
      document.getElementById('jupyterEditorView').style.display = 'none';
      document.getElementById('monacoEditorView').style.display = 'none';
      document.getElementById('collabEditorView').style.display = 'none';
      document.getElementById('browserView').style.display = 'none';
      document.getElementById('texpileEditorView').style.display = 'none';
      // 将 slides 编辑器移回主容器（如果在分屏中的话）
      _moveSlidesEditorToMain();
      // 切换笔记数据（多标签页缓存）
      _slidesSwitchToNotebook(path);
      return;
    }
    if (tab && tab._isKmind) {
      document.getElementById('pdfViewer').style.display = 'none';
      document.getElementById('welcomeScreen').style.display = 'none';
      document.getElementById('vditor').style.display = 'none';
      document.getElementById('plainEditor').style.display = 'none';
      document.getElementById('slidesEditorView').style.display = 'none';
      document.getElementById('kmindEditorView').style.display = 'flex';
      document.getElementById('jupyterEditorView').style.display = 'none';
      document.getElementById('monacoEditorView').style.display = 'none';
      document.getElementById('collabEditorView').style.display = 'none';
      document.getElementById('browserView').style.display = 'none';
      document.getElementById('texpileEditorView').style.display = 'none';
      return;
    }
    if (tab && tab._isTexpile) {
      document.getElementById('pdfViewer').style.display = 'none';
      document.getElementById('welcomeScreen').style.display = 'none';
      document.getElementById('vditor').style.display = 'none';
      document.getElementById('plainEditor').style.display = 'none';
      document.getElementById('slidesEditorView').style.display = 'none';
      document.getElementById('kmindEditorView').style.display = 'none';
      document.getElementById('jupyterEditorView').style.display = 'none';
      document.getElementById('monacoEditorView').style.display = 'none';
      document.getElementById('collabEditorView').style.display = 'none';
      document.getElementById('browserView').style.display = 'none';
      document.getElementById('texpileEditorView').style.display = 'flex';
      return;
    }
    if (tab && tab._isJupyter) {
      document.getElementById('pdfViewer').style.display = 'none';
      document.getElementById('welcomeScreen').style.display = 'none';
      document.getElementById('vditor').style.display = 'none';
      document.getElementById('plainEditor').style.display = 'none';
      document.getElementById('slidesEditorView').style.display = 'none';
      document.getElementById('kmindEditorView').style.display = 'none';
      document.getElementById('jupyterEditorView').style.display = 'flex';
      document.getElementById('monacoEditorView').style.display = 'none';
      document.getElementById('collabEditorView').style.display = 'none';
      document.getElementById('browserView').style.display = 'none';
      document.getElementById('texpileEditorView').style.display = 'none';
      return;
    }
    if (tab && tab._isMonaco) {
      document.getElementById('pdfViewer').style.display = 'none';
      document.getElementById('welcomeScreen').style.display = 'none';
      document.getElementById('vditor').style.display = 'none';
      document.getElementById('plainEditor').style.display = 'none';
      document.getElementById('slidesEditorView').style.display = 'none';
      document.getElementById('kmindEditorView').style.display = 'none';
      document.getElementById('jupyterEditorView').style.display = 'none';
      document.getElementById('monacoEditorView').style.display = 'flex';
      document.getElementById('collabEditorView').style.display = 'none';
      document.getElementById('browserView').style.display = 'none';
      document.getElementById('texpileEditorView').style.display = 'none';
      if (_monacoEditor) {
        _loadMonacoFile(path);
        setTimeout(function() { _monacoEditor.layout(); }, 50);
      }
      return;
    }
    if (tab && tab._isCollab) {
      document.getElementById('pdfViewer').style.display = 'none';
      document.getElementById('welcomeScreen').style.display = 'none';
      document.getElementById('vditor').style.display = 'none';
      document.getElementById('plainEditor').style.display = 'none';
      document.getElementById('slidesEditorView').style.display = 'none';
      document.getElementById('kmindEditorView').style.display = 'none';
      document.getElementById('jupyterEditorView').style.display = 'none';
      document.getElementById('monacoEditorView').style.display = 'none';
      document.getElementById('collabEditorView').style.display = 'flex';
      document.getElementById('browserView').style.display = 'none';
      document.getElementById('texpileEditorView').style.display = 'none';
      // 触发协同实例打开（若未就绪）。已有实例时 open 内部直接返回，复用容器内 Vditor。
      if (window.CollabEditor && tab._srcPath) {
        var _alreadyHas = window.CollabEditor.hasInstance(tab._srcPath);
        window.CollabEditor.open(tab._srcPath, { containerId: 'collabEditorArea' });
        // 切回已有实例时，容器从 display:none 恢复，Vditor 内部布局可能失效，
        // 派发 resize 事件触发 Vditor 重新计算高度（Vditor 内部监听 window resize）
        if (_alreadyHas) {
          setTimeout(function() {
            try { window.dispatchEvent(new Event('resize')); } catch (e) {}
          }, 60);
        }
      }
      return;
    }
    if (tab && tab._isBrowser) {
      document.getElementById('pdfViewer').style.display = 'none';
      document.getElementById('welcomeScreen').style.display = 'none';
      document.getElementById('vditor').style.display = 'none';
      document.getElementById('plainEditor').style.display = 'none';
      document.getElementById('slidesEditorView').style.display = 'none';
      document.getElementById('kmindEditorView').style.display = 'none';
      document.getElementById('jupyterEditorView').style.display = 'none';
      document.getElementById('monacoEditorView').style.display = 'none';
      document.getElementById('collabEditorView').style.display = 'none';
      document.getElementById('officeEditorView').style.display = 'none';
      document.getElementById('browserView').style.display = 'flex';
      document.getElementById('texpileEditorView').style.display = 'none';
      _restoreBrowserFrame(tab);
      return;
    }
    if (tab && tab._isOffice) {
      document.getElementById('pdfViewer').style.display = 'none';
      document.getElementById('welcomeScreen').style.display = 'none';
      document.getElementById('vditor').style.display = 'none';
      document.getElementById('plainEditor').style.display = 'none';
      document.getElementById('slidesEditorView').style.display = 'none';
      document.getElementById('kmindEditorView').style.display = 'none';
      document.getElementById('jupyterEditorView').style.display = 'none';
      document.getElementById('monacoEditorView').style.display = 'none';
      document.getElementById('collabEditorView').style.display = 'none';
      document.getElementById('browserView').style.display = 'none';
      document.getElementById('officeEditorView').style.display = 'flex';
      document.getElementById('texpileEditorView').style.display = 'none';
      showOfficeEditor(path);
      return;
    }
    showEditor();
    setEditorContent(state.fileContents[path] || '');
  },

  _addRecent(path, name) {
    state.recentFiles = state.recentFiles.filter(f => f.path !== path);
    state.recentFiles.unshift({ path, name, time: Date.now() });
    if (state.recentFiles.length > 20) state.recentFiles.length = 20;
    try { localStorage.setItem('ts2_recent_files', JSON.stringify(state.recentFiles)); } catch(e) {}
    _saveSession();
  },

  /* 在分屏 pane 中打开文件 */
  async openInPane(path, paneId) {
    var ext = path.includes('.') ? ('.' + path.split('.').pop().toLowerCase()) : '';

    // 浏览器标签页
    if (path.startsWith('__browser__')) {
      var srcTab = state.openTabs.find(function(t) { return t.path === path; });
      var tabs = state['paneTabs_' + paneId] || [];
      if (tabs.find(t => t.path === path)) { this.switchInPane(path, paneId); return; }
      tabs.push({ path: path, name: srcTab ? srcTab.name : '浏览器', modified: false, _isBrowser: true, _browserUrl: srcTab ? srcTab._browserUrl || '' : '' });
      state['paneTabs_' + paneId] = tabs;
      var tabsEl = document.getElementById('editorTabs-' + paneId);
      if (tabsEl) { tabsEl.appendChild(_createPaneTabEl(path, srcTab ? srcTab.name : '浏览器', paneId, false)); }
      this.switchInPane(path, paneId);
      return;
    }

    // 图片文件 → 分屏图片浏览器标签页（多格式、多实例）
    if (_isImageFile(path)) {
      var tabs = state['paneTabs_' + paneId] || [];
      if (tabs.find(t => t.path === path)) { this.switchInPane(path, paneId); return; }
      var name = path.split('/').pop();
      tabs.push({ path, name, modified: false, _isImage: true });
      state['paneTabs_' + paneId] = tabs;
      var tabsEl = document.getElementById('editorTabs-' + paneId);
      if (tabsEl) {
        var tabBtn = _createPaneTabEl(path, name, paneId, false);
        tabsEl.appendChild(tabBtn);
      }
      this.switchInPane(path, paneId);
      this._addRecent(path, name);
      return;
    }

    // PDF 在分屏 pane 中用轻量查看器
    if (ext === '.pdf') {
      var tabs = state['paneTabs_' + paneId] || [];
      if (tabs.find(t => t.path === path)) { this.switchInPane(path, paneId); return; }
      var name = path.split('/').pop();
      tabs.push({ path, name, modified: false, _isPdf: true });
      state['paneTabs_' + paneId] = tabs;
      state['paneFileContents_' + paneId][path] = '';
      // 添加 tab
      var tabsEl = document.getElementById('editorTabs-' + paneId);
      if (tabsEl) {
        var tabBtn = _createPaneTabEl(path, name, paneId, true);
        tabsEl.appendChild(tabBtn);
      }
      this.switchInPane(path, paneId);
      // 加载 PDF 到分屏 canvas
      await loadPdfInPane(path, paneId);
      this._addRecent(path, name);
      return;
    }

    // HTML 文件在浏览器中打开
    if (ext === '.html' || ext === '.htm') {
      const encodedPath = path.split('/').map(s => encodeURIComponent(s)).join('/');
      window.open(API_BASE + '/api/file/download/' + encodedPath + '?preview=true', '_blank');
      return;
    }

    var tabs = state['paneTabs_' + paneId] || [];
    if (tabs.find(t => t.path === path)) {
      this.switchInPane(path, paneId);
      return;
    }
    let content = null;
    const res = await client.getFile(path);
    if (res.code === 0 && res.data) {
      content = res.data.content;
    } else {
      const srcRes = await client.api('/api/data/projects/readFile', { path });
      if (srcRes.code === 0 && srcRes.data) content = srcRes.data.content;
    }
    if (content === null) { showToast('打开失败: 文件未找到', 'error'); return; }

    var name = path.split('/').pop();
    state['paneFileContents_' + paneId][path] = content;
    state['paneOriginalContents_' + paneId] = state['paneOriginalContents_' + paneId] || {};
    state['paneOriginalContents_' + paneId][path] = content;
    var isCode = _isCodeFile(path);
    tabs.push({ path, name, modified: false, _isMonaco: isCode });
    state['paneTabs_' + paneId] = tabs;

    // 添加 tab 按钮
    var tabsEl = document.getElementById('editorTabs-' + paneId);
    if (tabsEl) {
      var tabBtn = _createPaneTabEl(path, name, paneId, false);
      tabsEl.appendChild(tabBtn);
    }

    this.switchInPane(path, paneId);
    this._addRecent(path, name);
    showToast('已打开: ' + name, 'info');
  },

  switchInPane(path, paneId) {
    // 保存前一个 pane 标签页的状态
    var prevPath = state['paneActiveTab_' + paneId];
    if (prevPath) {
      var prevTab = (state['paneTabs_' + paneId] || []).find(function(t) { return t.path === prevPath; });
      if (prevTab && prevTab._isBrowser) {
        var f = document.getElementById('paneBrowserFrame-' + paneId);
        var inp = document.getElementById('paneBrowserUrl-' + paneId);
        if (f && inp) {
          var val = inp.value.trim();
          if (val && !val.startsWith('http://') && !val.startsWith('https://')) val = 'https://' + val;
          prevTab._browserUrl = val;
        }
      } else if (prevTab && prevTab._isMonaco && state['paneMonaco_' + paneId]) {
        state['paneFileContents_' + paneId][prevPath] = state['paneMonaco_' + paneId].getValue();
      } else if (prevTab) {
        var prevVditor = state['paneVditor_' + paneId];
        if (prevVditor && state['paneVditorReady_' + paneId] && !prevTab._isPdf && !prevTab._isSlides && !prevTab._isImage) {
          var prevContent = prevVditor.getValue();
          if (isRmdPath(prevPath) && window.editorSourceToRmd) {
            try { prevContent = window.editorSourceToRmd(prevContent); } catch (e) {}
          }
          state['paneFileContents_' + paneId][prevPath] = prevContent;
        }
      }
    }

    if (window.autoSaveScheduler && prevPath && prevPath !== path && _autoSavePaneDirty(paneId)) {
      window.autoSaveScheduler.flush('pane', paneId);
    }
    state['paneActiveTab_' + paneId] = path;
    // 更新 tab 高亮
    var tabsEl = document.getElementById('editorTabs-' + paneId);
    if (tabsEl) {
      tabsEl.querySelectorAll('.tab').forEach(function(t) {
        t.classList.toggle('active', t.dataset.path === path);
      });
    }
    // 更新标题
    var titleEl = document.getElementById('paneTitle-' + paneId);
    if (titleEl) {
      var tab = (state['paneTabs_' + paneId] || []).find(function(t) { return t.path === path; });
      titleEl.textContent = (tab && tab._isBrowser ? '🌐 ' : (tab && tab._isImage ? '🖼️ ' : '📄 ')) + path.split('/').pop();
    }
    // 隐藏空提示
    var wrapper = document.getElementById('editorWrapper-' + paneId);
    if (wrapper) {
      var hintEl = wrapper.querySelector('.pane-empty-hint');
      if (hintEl) hintEl.style.display = 'none';
    }
    if (!wrapper) return;

    var tab = (state['paneTabs_' + paneId] || []).find(function(t) { return t.path === path; });
    // 非图片标签页时统一隐藏分屏图片浏览器（图片分支随后会重新显示）
    var _imgC = document.getElementById('paneImageContainer-' + paneId);
    if (_imgC) _imgC.style.display = 'none';

    if (tab && tab._isBrowser) {
      var vditorEl = document.getElementById('paneVditor-' + paneId);
      if (vditorEl) vditorEl.style.display = 'none';
      var pdfContainer = document.getElementById('panePdfContainer-' + paneId);
      if (pdfContainer) pdfContainer.style.display = 'none';
      var browserContainer = document.getElementById('paneBrowserContainer-' + paneId);
      if (browserContainer) {
        browserContainer.style.display = 'flex';
        var frame = document.getElementById('paneBrowserFrame-' + paneId);
        var inp = document.getElementById('paneBrowserUrl-' + paneId);
        if (frame && inp) {
          if (tab._browserUrl && tab._browserUrl !== frame.src) {
            frame.removeAttribute('srcdoc');
            _setFrameSandbox(frame, true);
            frame.src = '/api/browser/proxy?url=' + encodeURIComponent(tab._browserUrl);
            inp.value = tab._browserUrl;
          } else if (!tab._browserUrl) {
            inp.value = '';
            frame.removeAttribute('src');
            _setFrameSandbox(frame, false);
            _renderStartPageInPane(paneId);
          }
        }
      }
      var titleEl = document.getElementById('paneTitle-' + paneId);
      if (titleEl) titleEl.textContent = '🌐 ' + (tab.name || '浏览器');
    } else if (tab && tab._isPdf) {
      // 显示 PDF canvas
      var vditorEl = document.getElementById('paneVditor-' + paneId);
      if (vditorEl) vditorEl.style.display = 'none';
      var pdfContainer = document.getElementById('panePdfContainer-' + paneId);
      if (pdfContainer) pdfContainer.style.display = 'flex';
    } else if (tab && tab._isImage) {
      // 显示图片浏览器（多实例：每个标签页独立 src）
      var vditorEl = document.getElementById('paneVditor-' + paneId);
      if (vditorEl) vditorEl.style.display = 'none';
      var pdfContainer = document.getElementById('panePdfContainer-' + paneId);
      if (pdfContainer) pdfContainer.style.display = 'none';
      var monacoEl = document.getElementById('paneMonaco-' + paneId);
      if (monacoEl) monacoEl.style.display = 'none';
      var imgContainer = document.getElementById('paneImageContainer-' + paneId);
      if (imgContainer) {
        imgContainer.style.display = 'flex';
        var img = document.getElementById('paneImageImg-' + paneId);
        if (img) img.src = _imageFileUrl(path);
        var nameEl = document.getElementById('paneImageName-' + paneId);
        if (nameEl) nameEl.textContent = tab.name || path.split('/').pop();
        _paneImgApply(paneId);
      }
      var titleEl = document.getElementById('paneTitle-' + paneId);
      if (titleEl) titleEl.textContent = '🖼️ ' + (tab.name || path.split('/').pop());
    } else if (tab && tab._isSlides) {
      // 隐藏 pane 默认编辑器，显示 slides 编辑器 UI
      var vditorEl = document.getElementById('paneVditor-' + paneId);
      if (vditorEl) vditorEl.style.display = 'none';
      var pdfContainer = document.getElementById('panePdfContainer-' + paneId);
      if (pdfContainer) pdfContainer.style.display = 'none';
      // 移入 slides 编辑器 DOM（含导航、大纲、Vditor 等全套 UI）
      _moveSlidesEditorToPane(paneId);
      // 切换笔记数据
      _slidesSwitchToNotebook(path);
    } else if (tab && tab._isMonaco) {
      var vditorEl = document.getElementById('paneVditor-' + paneId);
      if (vditorEl) vditorEl.style.display = 'none';
      var monacoEl = document.getElementById('paneMonaco-' + paneId);
      if (monacoEl) monacoEl.style.display = '';
      var pdfContainer = document.getElementById('panePdfContainer-' + paneId);
      if (pdfContainer) pdfContainer.style.display = 'none';
      var content = state['paneFileContents_' + paneId][path] || '';
      _ensurePaneMonaco(paneId, content, path);
    } else {
      var vditorEl = document.getElementById('paneVditor-' + paneId);
      if (vditorEl) vditorEl.style.display = '';
      var monacoEl = document.getElementById('paneMonaco-' + paneId);
      if (monacoEl) monacoEl.style.display = 'none';
      var pdfContainer = document.getElementById('panePdfContainer-' + paneId);
      if (pdfContainer) pdfContainer.style.display = 'none';
      // 设置 Vditor 内容
      var vditorInstance = state['paneVditor_' + paneId];
      var content = state['paneFileContents_' + paneId][path] || '';
      if (vditorInstance && state['paneVditorReady_' + paneId]) {
        if (isRmdPath(path) && window.rmdToEditorSource) {
          try { content = window.rmdToEditorSource(content); } catch (e) {}
        }
        vditorInstance.setValue(content);
      }
    }
    _saveSession();
  }
};

// ─── 会话持久化（刷新恢复） ───────────────────────────────

function _saveSession() {
  try {
    var panes = {};
    Object.keys(state).forEach(function(key) {
      if (key.startsWith('paneTabs_') && key !== 'paneTabs_0') {
        var pid = key.substring(9);
        var arr = state[key];
        if (Array.isArray(arr) && arr.length) {
          var normalTabs = arr.filter(function(t) { return !t._isSlides && !t._isBrowser; });
          if (normalTabs.length) {
            panes[pid] = {
              tabs: normalTabs.map(function(tab) {
                var obj = { path: tab.path, name: tab.name };
                if (tab._isPdf) {
                  var pp = state['panePdfPage_' + pid];
                  if (pp) {
                    obj.pdfState = {
                      pageNum: pp,
                      zoom: state['panePdfZoom_' + pid] || 1.0,
                      dualPage: state['panePdfDualPage_' + pid] || false
                    };
                  }
                }
                return obj;
              }),
              activeTab: state['paneActiveTab_' + pid] || null
            };
          }
        }
      }
    });
    localStorage.setItem('ts2_session', JSON.stringify({
      openTabs: state.openTabs.filter(function(t) { return !t._isSlides && !t._isWelcome; }).map(function(t) {
        var obj = { path: t.path, name: t.name };
        if (t._isPdf && state.pdfViewState[t.path]) {
          obj.pdfState = state.pdfViewState[t.path];
        }
        // 协同副本：持久化 srcPath 以便恢复时重新发起协同会话
        if (t._isCollab && t._srcPath) {
          obj._isCollab = true;
          obj._srcPath = t._srcPath;
        }
        return obj;
      }),
      activeTab: state.activeTab,
      panes: panes
    }));
  } catch(e) { console.warn('_saveSession error:', e); }
}

function _checkSessionRestore() {
  var saved;
  try { saved = JSON.parse(localStorage.getItem('ts2_session')); } catch(e) {}
  if (!saved) return;
  var hasTabs = saved.openTabs && saved.openTabs.length > 0;
  var hasPanes = saved.panes && Object.keys(saved.panes).length > 0;
  if (!hasTabs && !hasPanes) return;
  var fileItems = [];
  // 主编辑器标签页
  saved.openTabs.forEach(function(t) {
    var ext = t.path.includes('.') ? t.path.split('.').pop().toLowerCase() : '';
    var icon = ['pdf'].includes(ext) ? '📄' : ['py','js','ts','jsx','tsx','go','rs','java','cpp','c','h','rb','php','swift','kt','r','sh','bash','css','scss','less','vue','svelte','json','xml','yaml','yml','toml','sql','tex','md'].includes(ext) ? '📝' : '📄';
    fileItems.push('<div style="padding:3px 0;font-size:13px">📌 ' + icon + ' ' + escapeHtml(t.name) + '</div>');
  });
  // 分屏 pane 标签页
  if (hasPanes) {
    Object.keys(saved.panes).forEach(function(pid) {
      var p = saved.panes[pid];
      if (p && p.tabs) {
        p.tabs.forEach(function(t) {
          var ext = t.path.includes('.') ? t.path.split('.').pop().toLowerCase() : '';
          var icon = ['pdf'].includes(ext) ? '📄' : ['py','js','ts','jsx','tsx','go','rs','java','cpp','c','h','rb','php','swift','kt','r','sh','bash','css','scss','less','vue','svelte','json','xml','yaml','yml','toml','sql','tex','md'].includes(ext) ? '📝' : '📄';
          fileItems.push('<div style="padding:3px 0;font-size:13px;color:var(--fg-muted)">⬜ ' + icon + ' ' + escapeHtml(t.name) + '</div>');
        });
      }
    });
  }
  if (!fileItems.length) return;
  showHtmlModal('♻️ 恢复上次会话', '<div style="padding:12px"><p style="margin:0 0 12px;font-size:13px;color:var(--fg-muted)">检测到上次退出时打开的标签页：</p><div style="max-height:300px;overflow-y:auto;background:var(--bg);border-radius:6px;padding:8px 12px;border:1px solid var(--border);margin-bottom:12px">' + fileItems.join('') + '</div><div style="display:flex;gap:8px;justify-content:flex-end"><button class="btn-action" onclick="restoreSession()" style="padding:8px 20px">恢复</button><button class="btn" onclick="closeHtmlModal();clearSavedSession()" style="padding:8px 20px">忽略</button></div></div>', '480px');
}

function restoreSession() {
  closeHtmlModal();
  var saved;
  try { saved = JSON.parse(localStorage.getItem('ts2_session')); } catch(e) {}
  if (!saved || !saved.openTabs) return;
  localStorage.removeItem('ts2_session');
  var tabs = saved.openTabs;
  var paneData = saved.panes || {};
  var paneKeys = Object.keys(paneData);
  var idx = 0;
  function openNext() {
    if (idx >= tabs.length) {
      if (saved.activeTab && state.openTabs.find(function(t) { return t.path === saved.activeTab; })) {
        switchToTab(saved.activeTab);
      }
      if (!paneKeys.length) return;
      // 恢复分屏 pane
      for (var pi = 0; pi < paneKeys.length; pi++) {
        splitPane('editor', 'h');
      }
      setTimeout(function() {
        var paneEls = document.querySelectorAll('#splitContainer > .pane[data-pane-id]:not([data-pane-id="0"])');
        paneEls.forEach(function(el, i) {
          if (i >= paneKeys.length) return;
          var newPid = el.getAttribute('data-pane-id');
          var data = paneData[paneKeys[i]];
          if (!data || !data.tabs || !data.tabs.length) return;
          var pIdx = 0;
          function openPaneTab() {
            if (pIdx >= data.tabs.length) {
              if (data.activeTab) {
                setActivePane(newPid);
                setTimeout(function() { editorService.switchInPane(data.activeTab, newPid); }, 100);
              }
              return;
            }
            var tabData = data.tabs[pIdx++];
            if (tabData.pdfState) {
              state['panePdfPage_' + newPid] = tabData.pdfState.pageNum;
              state['panePdfZoom_' + newPid] = tabData.pdfState.zoom;
              state['panePdfDualPage_' + newPid] = tabData.pdfState.dualPage;
            }
            editorService.openInPane(tabData.path, newPid).then(openPaneTab).catch(function(e) { console.warn('恢复 pane tab 失败', e); openPaneTab(); });
          }
          openPaneTab();
        });
      }, 200);
      return;
    }
    var tabData = tabs[idx++];
    if (tabData.pdfState) {
      state.pdfViewState[tabData.path] = tabData.pdfState;
    }
    // 协同副本：走 openCollabCopy 重新发起协同会话（虚拟路径不能走 openFile）
    if (tabData._isCollab && tabData._srcPath) {
      openCollabCopy(tabData._srcPath).then(openNext).catch(function(e) { console.warn('恢复协同 tab 失败', e); openNext(); });
      return;
    }
    openFile(tabData.path, true).then(openNext).catch(function(e) { console.warn('恢复 tab 失败', e); openNext(); });
  }
  openNext();
}

function clearSavedSession() {
  try { localStorage.removeItem('ts2_session'); } catch(e) {}
}

// ─── Pandoc ::: fenced div preservation for Vditor ──────
// ::语法在Vditor WYSIWYG里会被吃掉换行，这里在getValue出口处修复。
// 原理：将:::…行/…:::行中被合并的换行复原。
function setupPandocDivPreservation(v) {
  if (!v || v._pandocDivSetup) return;
  v._pandocDivSetup = true;
  function fixPandocDivs(md) {
    if (!md || md.indexOf(':::') === -1) return md;
    function splitLine(raw) {
      var t = raw.trim();
      var idx = t.indexOf(':::');
      if (idx === -1) return [raw];
      var before = t.slice(0, idx).trim();   // ::: 之前的前缀/内容
      var after = t.slice(idx);              // 从 ::: 开始
      // 开标记: ":::类型 内容" / "::: 类型 内容" / "前缀 ::: 类型 内容"
      var m = /^:::\s*([a-zA-Z_][\w-]*)\s*(.*)$/.exec(after);
      if (m) {
        var res = [];
        // 前缀是纯引用/列表标记（Vditor 破坏残留）→ 丢弃；否则保留
        var mark = /^(?:>{1,}|[-*+]|\d+[.)])\s*$/.test(before);
        if (before && !mark) res.push(before);
        res.push(':::' + m[1]);              // ::: 强制顶格
        if (m[2]) res = res.concat(splitLine(m[2]));
        return res;
      }
      // 纯闭标记: ":::"
      if (/^:::\s*$/.test(after)) {
        var r = [];
        if (before) r.push(before);
        r.push(':::');                       // ::: 强制顶格
        return r;
      }
      // 无法识别（如 "::: 世界" 非标记用法）→ 保留原行
      return [raw];
    }
    var out = [];
    var lines = md.split('\n');
    for (var i = 0; i < lines.length; i++) {
      if (lines[i].indexOf(':::') === -1) { out.push(lines[i]); continue; }
      var split = splitLine(lines[i]);
      for (var j = 0; j < split.length; j++) out.push(split[j]);
    }
    return out.join('\n');
  }
  var origGetValue = v.getValue.bind(v);
  v.getValue = function() { return fixPandocDivs(origGetValue()); };
}

// 接管 Vditor 代码块渲染：保留完整 info string（如 ```{r, echo=FALSE}）
// 模块级函数：主编辑器与分屏 pane 共用（pane 无法访问 initVditor 内的局部函数）
function setupCodeBlockPreservation(v) {
  if (!v || !v.lute || v._codeBlockSetup) return;
  v._codeBlockSetup = true;
  // 1) 在 Lute 渲染时同时写入 data-info（完整 info string）
  try {
    v.lute.SetJSRenderers({
      renderers: {
        Md2VditorDOM: {
          renderCodeBlock: function(n, entering) {
            if (!entering || !n.Info) return ["", 2];
            var info = n.Info.Text || '';
            if (!info) return ["", 2];
            var content = (n.Content && n.Content.Text) || '';
            var lang = info.replace(/^\{?([^,\s\}]+).*/, '$1');
            var ec = content.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
            var ei = info.replace(/&/g,'&amp;').replace(/"/g,'&quot;');
            var el = lang.replace(/"/g,'&quot;');
            return ['<div class="vditor-wysiwyg__block" data-type="code-block"' +
              ' data-language="' + el + '" data-info="' + ei + '">' +
              '<div class="vditor-wysiwyg__preview" data-render="2">' +
              '<code class="language-' + el + '">' + ec + '</code></div>' +
              '<pre><code>' + ec + '<wbr></code></pre></div>', 2];
          }
        },
        Md2VditorIRDOM: {
          renderCodeBlock: function(n, entering) {
            if (!entering || !n.Info) return ["", 2];
            var info = n.Info.Text || '';
            if (!info) return ["", 2];
            var content = (n.Content && n.Content.Text) || '';
            var lang = info.replace(/^\{?([^,\s\}]+).*/, '$1');
            var ec = content.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
            var ei = info.replace(/&/g,'&amp;').replace(/"/g,'&quot;');
            var el = lang.replace(/"/g,'&quot;');
            return ['<div class="vditor-ir__block" data-type="code-block"' +
              ' data-language="' + el + '" data-info="' + ei + '">' +
              '<div class="vditor-ir__preview" data-render="2">' +
              '<code class="language-' + el + '">' + ec + '</code></div>' +
              '<pre><code>' + ec + '<wbr></code></pre></div>', 2];
          }
        }
      }
    });
  } catch(e) { console.warn('code block setup error:', e); }
  // 2) MutationObserver 兜底：当 Lute 重新渲染时同步 data-info
  function syncCodeBlocks(root) {
    if (!root) return;
    root.querySelectorAll('[data-type="code-block"]').forEach(function(el) {
      // 用户可能已手动编辑 data-language（如输入 {r, echo=TRUE}）
      var lang = el.getAttribute('data-language') || '';
      if (lang && !el.getAttribute('data-info')) {
        el.setAttribute('data-info', lang);
      }
    });
  }
  var observer = null;
  // 若同一 Vditor 实例已有 observer，先 disconnect（重建场景）
  if (v._codeBlockObserver) {
    try { v._codeBlockObserver.disconnect(); } catch (e) {}
    v._codeBlockObserver = null;
  }
  try {
    observer = new MutationObserver(function(muts) {
      for (var i = 0; i < muts.length; i++) {
        if (muts[i].type !== 'childList') continue;
        for (var j = 0; j < muts[i].addedNodes.length; j++) {
          var nd = muts[i].addedNodes[j];
          if (nd.nodeType !== 1 || !nd.getAttribute) continue;
          if (nd.getAttribute('data-type') === 'code-block') {
            var lang = nd.getAttribute('data-language') || '';
            if (lang && !nd.getAttribute('data-info')) {
              nd.setAttribute('data-info', lang);
            }
          } else if (nd.querySelectorAll) {
            nd.querySelectorAll('[data-type="code-block"]').forEach(function(el) {
              var lang = el.getAttribute('data-language') || '';
              if (lang && !el.getAttribute('data-info')) {
                el.setAttribute('data-info', lang);
              }
            });
          }
        }
      }
    });
  } catch(e) {}
  setTimeout(function() {
    var ed = v.vditor && (v.vditor.wysiwyg || v.vditor.ir);
    if (ed && ed.element && observer) {
      observer.observe(ed.element, { childList: true, subtree: true });
      v._codeBlockObserver = observer;  // 存入实例，便于后续 disconnect
      syncCodeBlocks(ed.element);
    }
  }, 50);
  // 3) 包装 getValue：保存前用 data-info 替换 data-language，然后恢复
  var origGetValue = v.getValue.bind(v);
  v.getValue = function() {
    var ed = v.vditor && (v.vditor.wysiwyg || v.vditor.ir);
    if (ed && ed.element) {
      syncCodeBlocks(ed.element);
      var restore = [];
      ed.element.querySelectorAll('[data-type="code-block"]').forEach(function(el) {
        var info = el.getAttribute('data-info') || '';
        if (info && info !== el.getAttribute('data-language')) {
          restore.push({el: el, lang: el.getAttribute('data-language')});
          el.setAttribute('data-language', info);
        }
      });
      try { return origGetValue(); }
      finally { restore.forEach(function(r) { r.el.setAttribute('data-language', r.lang); }); }
    }
    return origGetValue();
  };
}

// ─── 第三方依赖 CDN fallback 加载器 ─────────────────────────
// 本地资源加载失败时按 URL 列表依次回退到 CDN（unpkg → jsdelivr → cdnjs）
// 注：static/vditor 目录未随仓库部署（缺失），Vditor 内部资源（i18n/css/lute）
// 统一走 CDN 基址 __VDITOR_CDN（Vditor cdn 参数内部拼 {cdn}/dist/...）。
var __VDITOR_CDN = 'https://unpkg.com/vditor@3.10.7';
var __libFallbackMap = {
  'Vditor': [
    '/static/vditor/index.min.js',
    'https://unpkg.com/vditor@3.10.7/dist/index.min.js',
    'https://cdn.jsdelivr.net/npm/vditor@3.10.7/dist/index.min.js'
  ],
  'Lute': [
    'https://unpkg.com/vditor@3.10.7/dist/js/lute/lute.min.js',
    'https://cdn.jsdelivr.net/npm/vditor@3.10.7/dist/js/lute/lute.min.js'
  ],
  'katex': [
    '/static/vditor/js/katex/katex.min.js',
    'https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/katex.min.js',
    'https://unpkg.com/katex@0.16.9/dist/katex.min.js'
  ],
  'Terminal': [
    '/static/xterm.min.js',
    'https://cdn.jsdelivr.net/npm/@xterm/xterm@5.3.0/lib/xterm.min.js',
    'https://unpkg.com/@xterm/xterm@5.3.0/lib/xterm.min.js'
  ],
  'cytoscape': [
    '/static/cytoscape.min.js',
    'https://cdn.jsdelivr.net/npm/cytoscape@3.28.1/dist/cytoscape.min.js',
    'https://unpkg.com/cytoscape@3.28.1/dist/cytoscape.min.js'
  ],
  'pdfjsLib': [
    'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js',
    'https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/build/pdf.min.js',
    'https://unpkg.com/pdfjs-dist@3.11.174/build/pdf.min.js'
  ]
};

/**
 * 按全局对象名确保第三方库已加载；缺失时按 URL 列表依次动态加载（本地 → CDN 兜底）。
 * @param {string} globalName  全局对象名（如 'Vditor' / 'katex' / 'Terminal'）
 * @param {function(boolean)} done 加载完成回调（ok=true 表示可用）
 */
function ensureLib(globalName, done) {
  try {
    if (window[globalName]) { done && done(true); return; }
  } catch (e) { /* fallthrough */ }
  var urls = __libFallbackMap[globalName] || [];
  if (!urls.length) { done && done(false); return; }
  var idx = 0;
  function load() {
    if (idx >= urls.length) { done && done(false); return; }
    var s = document.createElement('script');
    s.src = urls[idx++];
    s.async = true;
    s.onload = function() {
      var ok = false;
      try { ok = !!window[globalName]; } catch (e) {}
      done && done(ok);
    };
    s.onerror = function() { s.remove(); load(); };
    document.head.appendChild(s);
  }
  load();
}

/**
 * 确保 Vditor 实例的 Lute 引擎就绪。
 * Vditor 内部异步加载 lute（{cdn}/dist/js/lute/lute.min.js），失败时不重试，
 * 此时 this.lute 为 undefined，setValue → e.lute.Md2VditorDOM 直接崩溃。
 * 未就绪时按多 CDN 兜底加载（unpkg → jsdelivr）并手动挂载 v.lute。
 * @param {object} v Vditor 实例
 * @param {function} done 就绪回调（无论成败都会调用，调用方需再次判空保护）
 */
function __ensureVditorLute(v, done) {
  if (!v || v.lute) { done && done(); return; }
  ensureLib('Lute', function (ok) {
    if (ok && window.Lute && v && !v.lute) {
      try {
        var L = window.Lute;
        // GopherJS 编译产物：window.Lute 是命名空间对象，用 New() 工厂创建实例
        if (L && typeof L.New === 'function') { v.lute = L.New(); }
        else if (typeof L === 'function') { v.lute = new L(); }
        else if (L && typeof L.default === 'function') { v.lute = new L.default(); }
      } catch (e) { console.warn('Lute 初始化失败:', e); }
    }
    if (!v.lute) console.warn('Lute 加载失败，Markdown 渲染可能不可用');
    done && done();
  });
}

// ─── Vditor Editor ──────────────────────────────────────────

function initVditor() {
  if (state.vditorReady) return;

  // If Vditor is not loaded yet, load the script dynamically（本地失败 → CDN fallback）
  if (typeof Vditor === 'undefined') {
    const existingScript = document.getElementById('vditorScriptTag');
    if (existingScript) {
      const newScript = document.createElement('script');
      newScript.id = 'vditorScriptTag';
      newScript.src = existingScript.src;
      newScript.onload = () => initVditor();
      newScript.onerror = () => {
        // 本地加载失败：CDN 回退（unpkg → jsdelivr），全部失败才切原生编辑器
        showToast('本地 Vditor 加载失败，尝试 CDN 回退…', 'info');
        ensureLib('Vditor', function(ok) {
          if (ok) {
            showToast('已通过 CDN 加载 Vditor', 'success');
            initVditor();
          } else {
            showToast('Vditor 加载失败，切换到原生编辑器', 'error');
            state.editorMode = 'plain';
            document.getElementById('vditor').style.display = 'none';
            document.getElementById('plainEditor').style.display = 'block';
          }
        });
      };
      existingScript.replaceWith(newScript);
      return;
    }
  }

  const acCfg = loadAcConfig();
  var currentTheme = document.documentElement.getAttribute('data-theme') || 'dark';

  var _vditorLight = isLightTheme(currentTheme);
  state.vditor = new Vditor('vditor', {
    height: '100%',
    mode: 'wysiwyg',
    theme: _vditorLight ? 'classic' : 'dark',
    icon: 'material',
    cdn: __VDITOR_CDN,
    _lutePath: __VDITOR_CDN + '/dist/js/lute/lute.min.js',
    placeholder: '开始输入...',
    math: {
      engine: 'KaTeX',
      inlineDigit: true,
    },
    cache: {
      enable: false,
    },
    hint: {
      delay: 30,  // 极低延迟，近乎实时响应（原 200ms）
      parse: false,
      extend: buildHintExtends(acCfg),
    },
    tab: '\t',
    markdown: {
      linkBase: `${API_BASE}/api/file/download/`,
    },
    preview: {
      markdown: {
        linkBase: `${API_BASE}/api/file/download/`,
      },
      theme: {
        current: _vditorLight ? 'light' : 'dark',
        path: __VDITOR_CDN + '/dist/css/content-theme',
      },
      hljs: {
        style: _vditorLight ? 'github' : 'tokyo-night-dark',
        lineNumber: true,
      },
      math: {
        engine: 'KaTeX',
        inlineDigit: true,
      },
    },
    upload: {
      url: `${API_BASE}/api/file/upload`,
      fieldName: 'files',
      extraData: () => ({ path: state.currentDir || '' }),
      handler: null,
      format: (files, responseText) => {
        try {
          const res = JSON.parse(responseText);
          if (res.code === 0 && res.data && res.data.uploaded) {
            return JSON.stringify({
              msg: '',
              code: 0,
              data: {
                errFiles: [],
                succMap: res.data.uploaded.reduce((m, f) => {
                  m[f.name] = f.url || client.getDownloadUrl(f.path);
                  return m;
                }, {})
              }
            });
          }
        } catch (e) {}
        return responseText;
      },
    },
    value: '',
    after: () => {
      __ensureVditorLute(state.vditor, function () {
        state.vditorReady = true;
        if (window.EditorChunks && window.EditorChunks.isEnabled()) {
          var _full = window.EditorChunks.takeFull();
          // 防御：takeFull 可能返回空（chunk 状态残留但 src 为空），绝不 setValue 覆盖成空白
          if (_full != null && _full !== '') state.vditor.setValue(_full);
        }
        if (state._pendingEditorSource != null) {
          var _p = state._pendingEditorSource;
          state._pendingEditorSource = null;
          _applyEditorSource(_p);
        }
        setupCodeBlockPreservation(state.vditor);
        setupPandocDivPreservation(state.vditor);
        bindVditorShortcuts(state.vditor);
        var _cont = document.getElementById('vditor');
        if (_cont) {
          if (window.enhanceRmdChunks) { try { window.enhanceRmdChunks(_cont, state.vditor); } catch (e) {} }
          if (window.initRmdChunksWatcher) { try { window.initRmdChunksWatcher(_cont, state.vditor); } catch (e) {} }
        }
      });
    },
    input: () => {
      if (!state.activeTab) return;
      // chunk 模式下 vditor.getValue() 只是当前块文本，不能用来更新 state.fileContents
      // （会覆盖完整内容缓存，导致切回标签页时加载块文本 → 内容丢失）
      // state.fileContents 保持上次正确值；saveCurrentFile/switchTo 通过 getEditorContent() 获取完整内容
      if (window.EditorChunks && window.EditorChunks.isEnabled()) {
        markTabModified(state.activeTab, true);
        if (window.autoSaveScheduler) window.autoSaveScheduler.schedule('main');
        return;
      }
      var content = state.vditor.getValue();
      // fileContents / modified 统一用 Rmd 语义（去掉编辑 meta line）比较
      var saved = content;
      if (isRmdPath(state.activeTab) && window.editorSourceToRmd) {
        try { saved = window.editorSourceToRmd(content); } catch (e) {}
      }
      state.fileContents[state.activeTab] = saved;
      markTabModified(state.activeTab, saved !== state.originalContents[state.activeTab]);
      if (window.autoSaveScheduler) window.autoSaveScheduler.schedule('main');
      // 正常模式：编辑后防抖刷新大纲（标题增删会同步反映）
      _scheduleEditorOutlineRefresh();
    },
  });
}

// ─── Vditor 快捷键绑定 ───────────────────────────────────
// Ctrl+M  插入行内公式 $...$（光标定位到公式内部）
// Ctrl+T  插入 Markdown 表格（3 列示例）
// 适用于主 Vditor / 分屏 Vditor / 幻灯片 Vditor
function bindVditorShortcuts(vd) {
  if (!vd || vd._shortcutsBound) return;
  vd._shortcutsBound = true;

  function getEditableEl() {
    try {
      var v = vd.vditor;
      if (!v) return null;
      var mode = v.currentMode || 'wysiwyg';
      var block = v[mode];
      return (block && block.element) ? block.element : null;
    } catch (e) { return null; }
  }

  var el = getEditableEl();
  if (!el) {
    // after 回调时 mode 可能未就绪，延迟重试
    setTimeout(function () { bindVditorShortcuts(vd); }, 100);
    return;
  }

  el.addEventListener('keydown', function (e) {
    if (!(e.ctrlKey || e.metaKey)) return;
    // Ctrl+Shift+M  → 块级公式
    // Ctrl+M        → 行内公式
    // Ctrl+T        → 表格
    if (e.altKey) return;
    var key = (e.key || '').toLowerCase();
    if (e.shiftKey && key === 'm') {
      e.preventDefault();
      e.stopPropagation();
      _vditorInsertBlockMath(vd);
    } else if (!e.shiftKey && key === 'm') {
      e.preventDefault();
      e.stopPropagation();
      _vditorInsertInlineMath(vd);
    } else if (!e.shiftKey && key === 't') {
      e.preventDefault();
      e.stopPropagation();
      _vditorInsertTable(vd);
    }
  }, true);  // capture 阶段，先于 Vditor 内部处理截获
}

// 插入行内公式 $...$
// 策略：只插入 $$，光标回退 1 字符到中间，用户直接输入公式内容
function _vditorInsertInlineMath(vd) {
  try {
    vd.focus();
    vd.insertValue('$$');
    // 光标回退 1 字符，落在两个 $ 之间
    var sel = window.getSelection();
    if (sel && sel.modify) {
      sel.modify('extend', 'backward', 'character');
      sel.collapseToStart();
    }
  } catch (e) {
    console.warn('[vditor] Ctrl+M 插入行内公式失败:', e);
  }
}

// 插入块级公式 $$...$$
// 策略：插入 $$ + 换行 + $$（前后空行包裹），光标落在两个 $$ 之间的空行
function _vditorInsertBlockMath(vd) {
  try {
    vd.focus();
    // 前后空行确保块级公式独立成块，中间留空行让用户输入
    vd.insertValue('\n$$\n\n$$\n');
    // 光标回退到中间空行：从末尾 \n 回退 4 字符（越过 \n、$、$、\n）
    var sel = window.getSelection();
    if (sel && sel.modify) {
      sel.modify('extend', 'backward', 'character');  // \n
      sel.modify('extend', 'backward', 'character');  // $
      sel.modify('extend', 'backward', 'character');  // $
      sel.modify('extend', 'backward', 'character');  // \n
      sel.collapseToStart();
    }
  } catch (e) {
    console.warn('[vditor] Ctrl+Shift+M 插入块级公式失败:', e);
  }
}

// 插入 Markdown 表格（3 列 2 行，光标落在第一个单元格）
function _vditorInsertTable(vd) {
  try {
    vd.focus();
    // 前导换行防止与前文粘连，末尾换行方便继续输入
    vd.insertValue('\n| 列1 | 列2 | 列3 |\n|---|---|---|\n|  |  |  |\n');
  } catch (e) {
    console.warn('[vditor] Ctrl+T 插入表格失败:', e);
  }
}

/* 为分屏 pane 初始化独立的 Vditor 实例 */
function initPaneVditor(paneId) {
  if (typeof Vditor === 'undefined') return;
  var vditorDiv = document.getElementById('paneVditor-' + paneId);
  if (!vditorDiv) return;
  // Vditor 容器和 PDF 容器已在 splitPane 中创建，这里只初始化 Vditor 实例
  if (state['paneVditorReady_' + paneId]) return;

  var currentTheme = document.documentElement.getAttribute('data-theme') || 'dark';
  var _vditorLight = isLightTheme(currentTheme);
  state['paneVditor_' + paneId] = new Vditor('paneVditor-' + paneId, {
    height: '100%',
    mode: 'wysiwyg',
    theme: _vditorLight ? 'classic' : 'dark',
    icon: 'material',
    cdn: __VDITOR_CDN,
    _lutePath: __VDITOR_CDN + '/dist/js/lute/lute.min.js',
    placeholder: '开始输入...',
    math: {
      engine: 'KaTeX',
      inlineDigit: true,
    },
    cache: { enable: false },
    tab: '\t',
    markdown: {
      linkBase: `${API_BASE}/api/file/download/`,
    },
    preview: {
      markdown: {
        linkBase: `${API_BASE}/api/file/download/`,
      },
      theme: { current: _vditorLight ? 'light' : 'dark', path: __VDITOR_CDN + '/dist/css/content-theme' },
      hljs: { style: _vditorLight ? 'github' : 'tokyo-night-dark', lineNumber: true },
      math: { engine: 'KaTeX', inlineDigit: true },
    },
    value: '',
    after: function() {
      var _pv = state['paneVditor_' + paneId];
      __ensureVditorLute(_pv, function () {
        state['paneVditorReady_' + paneId] = true;
        // 如果当前活动 tab 是 PDF，初始化完成后隐藏 Vditor
        var activePath = state['paneActiveTab_' + paneId];
        var activeTab = (state['paneTabs_' + paneId] || []).find(function(t) { return t.path === activePath; });
        if (activeTab && activeTab._isPdf) {
          var vditorEl = document.getElementById('paneVditor-' + paneId);
          if (vditorEl) vditorEl.style.display = 'none';
        }
        setupCodeBlockPreservation(_pv);
        setupPandocDivPreservation(_pv);
        bindVditorShortcuts(_pv);
        var _cont = document.getElementById('paneVditor-' + paneId);
        if (_cont) {
          if (window.enhanceRmdChunks) { try { window.enhanceRmdChunks(_cont, _pv); } catch (e) {} }
          if (window.initRmdChunksWatcher) { try { window.initRmdChunksWatcher(_cont, _pv); } catch (e) {} }
        }
      });
    },
    input: function() {
      var activePath = state['paneActiveTab_' + paneId];
      if (!activePath) return;
      var content = state['paneVditor_' + paneId].getValue();
      // paneFileContents / modified 统一用 Rmd 语义（去掉编辑 meta line）比较
      var saved = content;
      if (isRmdPath(activePath) && window.editorSourceToRmd) {
        try { saved = window.editorSourceToRmd(content); } catch (e) {}
      }
      state['paneFileContents_' + paneId][activePath] = saved;
      var tabs = state['paneTabs_' + paneId] || [];
      var tab = tabs.find(function(t) { return t.path === activePath; });
      if (tab) {
        var orig = (state['paneOriginalContents_' + paneId] || {})[activePath];
        tab.modified = saved !== orig;
        // 更新 tab 修改标记点
        var tabsEl = document.getElementById('editorTabs-' + paneId);
        if (tabsEl) {
          var tabEl = tabsEl.querySelector('.tab[data-path="' + activePath + '"]');
          if (tabEl) {
            var modDot = tabEl.querySelector('.modified');
            if (modDot) modDot.style.display = tab.modified ? 'inline-block' : 'none';
          }
        }
      }
      if (window.autoSaveScheduler) window.autoSaveScheduler.schedule('pane', paneId);
    },
  });
}

/* 分屏 pane 中加载 PDF */
async function loadPdfInPane(path, paneId) {
  var data = await client.downloadBinary(path);
  if (!data || data.code === -1) {
    showToast('打开 PDF 失败', 'error');
    return;
  }
  try {
    var pdf = await pdfjsLib.getDocument({ data: data }).promise;
    state['panePdfDoc_' + paneId] = pdf;
    if (!state['panePdfPage_' + paneId]) state['panePdfPage_' + paneId] = 1;
    if (!state['panePdfZoom_' + paneId]) state['panePdfZoom_' + paneId] = 1.0;
    await renderPanePdfPage(paneId);
  } catch (e) {
    showToast('PDF 渲染失败: ' + e.message, 'error');
  }
}

async function renderPanePdfPage(paneId) {
  var pdf = state['panePdfDoc_' + paneId];
  if (!pdf) return;
  var pageNum = state['panePdfPage_' + paneId] || 1;
  var zoom = state['panePdfZoom_' + paneId] || 1.0;
  var dual = state['panePdfDualPage_' + paneId] || false;
  var canvas = document.getElementById('panePdfCanvas-' + paneId);
  var canvas2 = document.getElementById('panePdfCanvas2-' + paneId);
  if (!canvas) return;

  var container = canvas.parentElement;
  var containerWidth = container ? container.clientWidth - 16 : 600;
  var availW = dual ? (containerWidth - 3) / 2 : containerWidth;
  var dpr = window.devicePixelRatio || 1;

  var page = await pdf.getPage(pageNum);
  var baseViewport = page.getViewport({ scale: 1.0 });
  var fitScale = availW / baseViewport.width;
  var baseScale = Math.min(fitScale * zoom, 3.0);
  var renderScale = baseScale * dpr * 1.5;
  var viewport = page.getViewport({ scale: renderScale });

  canvas.width = viewport.width;
  canvas.height = viewport.height;
  var cssWidth = baseScale * baseViewport.width;
  var cssHeight = baseScale * baseViewport.height;
  canvas.style.width = cssWidth + 'px';
  canvas.style.height = cssHeight + 'px';
  canvas.style.display = '';
  canvas.style.boxShadow = '0 2px 12px rgba(0,0,0,0.3)';
  var ctx = canvas.getContext('2d');

  // 双页：准备第二页
  var page2 = null, viewport2 = null, ctx2 = null;
  if (dual && pageNum < pdf.numPages) {
    page2 = await pdf.getPage(pageNum + 1);
    var baseViewport2 = page2.getViewport({ scale: 1.0 });
    var fitScale2 = availW / baseViewport2.width;
    var baseScale2 = Math.min(fitScale2 * zoom, 3.0);
    var renderScale2 = baseScale2 * dpr * 1.5;
    viewport2 = page2.getViewport({ scale: renderScale2 });
    canvas2.width = viewport2.width;
    canvas2.height = viewport2.height;
    canvas2.style.width = (baseScale2 * baseViewport2.width) + 'px';
    canvas2.style.height = (baseScale2 * baseViewport2.height) + 'px';
    canvas2.style.display = '';
    canvas2.style.boxShadow = '0 2px 12px rgba(0,0,0,0.3)';
    ctx2 = canvas2.getContext('2d');
  } else if (canvas2) {
    canvas2.style.display = 'none';
  }

  // 隐藏两个 canvas 一起渲染，避免闪烁
  canvas.style.visibility = 'hidden';
  if (dual && page2 && canvas2.style.display !== 'none') canvas2.style.visibility = 'hidden';

  var tasks = [page.render({ canvasContext: ctx, viewport }).promise];
  if (page2 && ctx2) tasks.push(page2.render({ canvasContext: ctx2, viewport: viewport2 }).promise);
  await Promise.all(tasks);

  canvas.style.visibility = '';
  if (dual && page2 && canvas2.style.display !== 'none') canvas2.style.visibility = '';

  // 容器排版
  if (container) {
    container.style.flexDirection = dual ? 'row' : 'column';
    container.style.alignItems = dual ? 'flex-start' : 'center';
    container.style.justifyContent = dual ? 'center' : 'flex-start';
    container.style.gap = dual ? '3px' : '';
  }

  var infoText = dual ?
    pageNum + '-' + Math.min(pageNum + 1, pdf.numPages) + '/' + pdf.numPages :
    pageNum + '/' + pdf.numPages;
  var infoEl = document.getElementById('panePdfInfo-' + paneId);
  if (infoEl) {
    infoEl.value = pageNum;
    infoEl.max = pdf.numPages;
  }
  var totalEl = document.getElementById('panePdfTotal-' + paneId);
  if (totalEl) totalEl.textContent = '/ ' + pdf.numPages;
  var zoomEl = document.getElementById('panePdfZoom-' + paneId);
  if (zoomEl) zoomEl.textContent = Math.round(zoom * 100) + '%';
}

function panePdfNav(paneId, delta) {
  var pdf = state['panePdfDoc_' + paneId];
  if (!pdf) return;
  var current = state['panePdfPage_' + paneId] || 1;
  var dual = state['panePdfDualPage_' + paneId] || false;
  var step = dual ? 2 : 1;
  var next = current + delta * step;
  if (next < 1 || next > pdf.numPages) return;
  state['panePdfPage_' + paneId] = next;
  renderPanePdfPage(paneId);
  _saveSession();
}

function panePdfGoToPage(paneId, page) {
  var pdf = state['panePdfDoc_' + paneId];
  if (!pdf) return;
  if (page < 1 || page > pdf.numPages || isNaN(page)) {
    var infoEl = document.getElementById('panePdfInfo-' + paneId);
    if (infoEl) infoEl.value = state['panePdfPage_' + paneId] || 1;
    return;
  }
  state['panePdfPage_' + paneId] = page;
  renderPanePdfPage(paneId);
  _saveSession();
}

function panePdfZoom(paneId, delta) {
  var current = state['panePdfZoom_' + paneId] || 1.0;
  var next = Math.max(0.3, Math.min(3.0, current + delta));
  state['panePdfZoom_' + paneId] = next;
  renderPanePdfPage(paneId);
  _saveSession();
}

function togglePanePdfDual(paneId) {
  var dual = !(state['panePdfDualPage_' + paneId] || false);
  state['panePdfDualPage_' + paneId] = dual;
  var pdf = state['panePdfDoc_' + paneId];
  if (pdf && dual) {
    var pageNum = state['panePdfPage_' + paneId] || 1;
    if (pageNum === pdf.numPages && pdf.numPages > 1) {
      state['panePdfPage_' + paneId] = pdf.numPages - 1;
    }
  }
  renderPanePdfPage(paneId);
  _saveSession();
}

// 分屏 PDF 目录
async function loadPanePdfOutline(paneId) {
  var pdf = state['panePdfDoc_' + paneId];
  if (!pdf) return;
  var container = document.getElementById('panePdfOutlineContent-' + paneId);
  if (!container) return;
  container.innerHTML = '';
  try {
    var outline = await pdf.getOutline();
    if (!outline || outline.length === 0) {
      container.innerHTML = '<div style="padding:6px 10px;color:var(--fg-muted);font-size:10px">此 PDF 无目录信息</div>';
      return;
    }
    await _renderPaneOutlineItems(outline, container, 0, paneId);
  } catch (e) {
    container.innerHTML = '<div style="padding:6px 10px;color:var(--fg-muted);font-size:10px">目录加载失败</div>';
  }
}

async function _renderPaneOutlineItems(items, container, depth, paneId) {
  for (var i = 0; i < items.length; i++) {
    var item = items[i];
    var el = document.createElement('div');
    el.className = 'pdf-outline-item';
    el.style.paddingLeft = (10 + depth * 14) + 'px';
    el.textContent = item.title;
    el.title = item.title;
    (function(it, element, pid) {
      var _resolve = async function() {
        if (!it.dest) return;
        try {
          var dest = it.dest;
          if (typeof dest === 'string') dest = await state['panePdfDoc_' + pid].getDestination(dest);
          if (dest && dest[0]) {
            var pageIdx = await state['panePdfDoc_' + pid].getPageIndex(dest[0]);
            element.dataset.pageNum = pageIdx + 1;
          }
        } catch (e) {}
      };
      _resolve();
    })(item, el, paneId);
    el.addEventListener('click', function() {
      var pn = parseInt(this.dataset.pageNum);
      var pdf = state['panePdfDoc_' + paneId];
      if (pn && pdf && pn >= 1 && pn <= pdf.numPages) {
        state['panePdfPage_' + paneId] = pn;
        renderPanePdfPage(paneId);
        container.querySelectorAll('.pdf-outline-item').forEach(function(e) { e.classList.remove('active'); });
        this.classList.add('active');
      }
    });
    container.appendChild(el);
    if (item.items && item.items.length > 0) {
      await _renderPaneOutlineItems(item.items, container, depth + 1, paneId);
    }
  }
}

function togglePanePdfOutline(paneId) {
  var panel = document.getElementById('panePdfOutline-' + paneId);
  if (!panel) return;
  if (panel.style.display === 'none' || panel.style.display === '') {
    panel.style.display = 'flex';
    loadPanePdfOutline(paneId);
  } else {
    panel.style.display = 'none';
  }
}

var _editorOutlineVisible = false;

function refreshEditorOutline() {
  if (!_editorOutlineVisible) return;
  var contentEl = document.getElementById('editorOutlineContent');
  if (!contentEl) return;
  // 检查当前活跃标签是否为协同编辑
  var activeTab = state.openTabs.find(function(t) { return t.path === state.activeTab; });
  if (activeTab && activeTab._isCollab && activeTab._srcPath && window.CollabEditor) {
    var collabVd = window.CollabEditor.getVditor(activeTab._srcPath);
    if (collabVd && collabVd.vditor) {
      var vd = collabVd.vditor;
      var modeEl = vd[vd.currentMode] && vd[vd.currentMode].element;
      if (modeEl) {
        try { Vditor.outlineRender(modeEl, contentEl, vd); } catch (e) {}
      }
      return;
    }
  }
  // 主编辑器逻辑
  if (!state.vditor || !state.vditorReady) return;
  initEditorChunks();
  if (window.EditorChunks && window.EditorChunks.isEnabled()) {
    try { window.EditorChunks.renderOutline(contentEl); } catch (e) {}
    return;
  }
  var vd = state.vditor.vditor;
  if (!vd) return;
  var modeEl = vd[vd.currentMode] && vd[vd.currentMode].element;
  if (!modeEl) return;
  try {
    Vditor.outlineRender(modeEl, contentEl, vd);
  } catch (e) {}
}

// 防抖刷新大纲：编辑输入时避免每次按键都重建大纲 DOM
var _editorOutlineRefreshTimer = null;
function _scheduleEditorOutlineRefresh() {
  if (!_editorOutlineVisible) return;
  if (_editorOutlineRefreshTimer) clearTimeout(_editorOutlineRefreshTimer);
  _editorOutlineRefreshTimer = setTimeout(function () {
    _editorOutlineRefreshTimer = null;
    refreshEditorOutline();
  }, 400);
}

function toggleEditorOutline() {
  _editorOutlineVisible = !_editorOutlineVisible;
  var panel = document.getElementById('editorOutlinePanel');
  var btn = document.getElementById('btnOutline');
  if (!panel) return;
  if (_editorOutlineVisible) {
    panel.style.display = '';
    if (btn) { btn.style.color = 'var(--accent)'; }
    refreshEditorOutline();
  } else {
    panel.style.display = 'none';
    if (btn) { btn.style.color = ''; }
  }
}

function _openEditorOutline() {
  _editorOutlineVisible = true;
  var panel = document.getElementById('editorOutlinePanel');
  var btn = document.getElementById('btnOutline');
  if (panel) panel.style.display = '';
  if (btn) btn.style.color = 'var(--accent)';
  refreshEditorOutline();
}

function initEditorChunks() {
  if (initEditorChunks._done || !window.EditorChunks) return;
  initEditorChunks._done = true;
  window.EditorChunks.attach({
    getVditor: function () { return state.vditor; },
    getActivePath: function () { return state.activeTab; },
    getEditorSource: function () {
      var c = getEditorContent();
      if (isRmdPath(state.activeTab)) {
        try { c = (window.rmdToEditorSource ? window.rmdToEditorSource(c) : c); } catch (e) {}
      }
      return c;
    },
    setValue: function (src) {
      if (state.vditorReady && state.vditor) state.vditor.setValue(src);
    },
    promptTitle: async function (defaultVal) {
      return await modalPrompt('给新分段命名', defaultVal || '新分段');
    },
    onStateChange: function () {
      _updateChunkNav();
      if (_editorOutlineVisible) refreshEditorOutline();
    }
  });
}

function _updateChunkNav() {
  var counter = document.getElementById('chunkNavCounter');
  var prev = document.getElementById('chunkPrevBtn');
  var next = document.getElementById('chunkNextBtn');
  var add = document.getElementById('chunkAddBtn');
  var tog = document.getElementById('chunkToggleBtn');
  if (!counter) return;
  var on = !!(window.EditorChunks && window.EditorChunks.isEnabled());
  if (on) {
    var ai = window.EditorChunks.getActiveIdx();
    var bc = window.EditorChunks.getBlockCount();
    counter.style.display = '';
    counter.textContent = (ai + 1) + '/' + bc;
    if (prev) { prev.disabled = ai <= 0; prev.style.opacity = ai <= 0 ? 0.4 : 1; prev.style.display = ''; }
    if (next) { next.disabled = ai >= bc - 1; next.style.opacity = ai >= bc - 1 ? 0.4 : 1; next.style.display = ''; }
    if (add) { add.style.display = ''; }
    if (tog) tog.style.color = 'var(--accent)';
  } else {
    counter.style.display = 'none';
    if (prev) { prev.style.display = 'none'; }
    if (next) { next.style.display = 'none'; }
    if (add) { add.style.display = 'none'; }
    if (tog) tog.style.color = '';
  }
}

function toggleChunkMode() {
  if (!window.EditorChunks) return;
  if (!state.vditorReady || !state.vditor) return;
  var wasOn = window.EditorChunks.isEnabled();
  window.EditorChunks.toggle();
  if (!wasOn && window.EditorChunks.isEnabled()) _openEditorOutline();
  _updateChunkNav();
}

function chunkPrev() {
  if (!window.EditorChunks) return;
  window.EditorChunks.prevBlock();
}

function chunkNext() {
  if (!window.EditorChunks) return;
  window.EditorChunks.nextBlock();
}

function injectToAgent() {
  if (!state.activeTab || state.activeTab === '__welcome__') return;
  var path = state.activeTab;
  var input = document.getElementById('agentInput');
  if (!input) return;
  if (state.agentMessages && state.agentMessages.length === 0) {
    try { initAgentPanel(); } catch (e) {}
  }
  switchNavTab('agent');
  var text = '当前文件地址: ' + path;
  if (input.value && input.value.trim()) {
    input.value = input.value.replace(/\s+$/, '') + ' ' + text;
  } else {
    input.value = text;
  }
  input.focus();
  try { input.scrollIntoView({ block: 'center' }); } catch (e) {}
  showToast('已将当前文件地址追加到 Agent 输入框，回车发送');
}

function injectAllTabsToAgent() {
  var paths = (state.openTabs || [])
    .filter(function (t) {
      return t && t.path && t.path !== '__welcome__' && !t._isSlides && !t._isKmind && !t._isJupyter;
    })
    .map(function (t) { return t.path; });
  var input = document.getElementById('agentInput');
  if (!input) return;
  if (state.agentMessages && state.agentMessages.length === 0) {
    try { initAgentPanel(); } catch (e) {}
  }
  switchNavTab('agent');
  var text = paths.length > 0
    ? '当前所有标签文件地址: ' + paths.join(' ')
    : '当前没有可用的文件标签';
  if (input.value && input.value.trim()) {
    input.value = input.value.replace(/\s+$/, '') + ' ' + text;
  } else {
    input.value = text;
  }
  input.focus();
  try { input.scrollIntoView({ block: 'center' }); } catch (e) {}
  showToast(paths.length > 0
    ? '已将 ' + paths.length + ' 个标签地址追加到 Agent 输入框，回车发送'
    : '没有可用的文件标签');
}

async function addChunkSection() {
  if (!window.EditorChunks || !window.EditorChunks.isEnabled()) return;
  var t = await modalPrompt('给新分段命名', '新分段');
  if (t == null) return;
  window.EditorChunks.addSection(t);
  _updateChunkNav();
}

