    if (/^https?:\/\//.test(trimmed.split('\n')[0])) {
      return '<div class="tc-friend"><div class="tc-friend-meta">🌐 <a href="' + escapeHtml(trimmed) + '" target="_blank" class="tc-fv-link">' + escapeHtml(trimmed) + '</a></div></div>';
    }
    return _genericResultView(r);
