    + '<div class="bm-filter"><input id="bmSearchInput" type="text" placeholder="搜索书签..." oninput="filterBms()">'
    + '<span style="font-size:11px;color:#565a7a;padding:4px 2px">分类:</span>'
    + catBtns + '</div>'
    + '<div class="bookmarks">' + addBmHtml + '</div>'
